"""Projetos do catálogo. Todos os registros com status "seed" entraram como semente e aguardam revisão humana.

Campos: id, title, year, by (autor), cat (categoria principal), also (formatos secundários), purposes, degree, tools, url, country,
featured, summary (EN/PT), human (onde entrou o humano, EN/PT), notslop (por que não é slop, EN/PT), status.
"""


def p(id, title, year, by, cat, purposes, degree, tools, summary_en, summary_pt, human_en, human_pt, notslop_en, notslop_pt,
      url="", country="", also=(), featured=False, status="seed"):
    return dict(id=id, title=title, year=year, by=by, cat=cat, also=list(also), purposes=list(purposes), degree=degree,
                tools=list(tools), url=url, country=country, featured=featured, status=status,
                summary=dict(en=summary_en, pt=summary_pt), human=dict(en=human_en, pt=human_pt), notslop=dict(en=notslop_en, pt=notslop_pt))


